#Region @DOC
#### Description:
#Creates a Git push plan and optionally executes it. Wraps the `POST /GitPush` REST API endpoint, and `}bedrock.git.plan.execute` when `pExecute = 1`.
#
#### How to Use:
#
#- `pMessage`: REQUIRED: the commit message.
#- `pEmail`: REQUIRED: the commit author's email.
#- `pAuthor`: OPTIONAL: the commit author. If blank, `<process name> called by user <TM1 user>` is used.
#- `pBranch`: the existing branch whose latest commit is the parent. Leave blank only for a brand new repository with no commits.
#- `pNewBranch`: OPTIONAL: create and push to this new branch instead of updating `pBranch`.
#- `pForce`: 1 = override precondition checks. Use with caution in production.
#- `pExecute`: 1 = execute the plan immediately. 0 = leave the plan pending, so it can be reviewed with `}bedrock.git.plan.get` and executed later with `}bedrock.git.plan.execute`.
#- `pConnectionName`: a connection name configured in `}bedrock.session.start`, or a connection-details JSON object returned by it. When a JSON object is passed, that session is reused and is not closed at the end of this process.
#- `pLogOutput`, `pStrictErrorHandling` and `pJson` work as in all bedrock processes.
#
#Credentials, depending on how the repository authenticates:
#- HTTPS: `pUsername` and `pPassword` (for GitHub, use a personal access token as the password).
#- SSH: `pPublicKey` and `pPrivateKey`, plus `pPassphrase` if the key has one.
#
#> [!WARNING]
#> Never save real credentials as parameter defaults. Defaults are stored in the process and exported with it.
#
#### Return Value:
#`sBedrockReturnValue` is set to the plan-creation response, whether or not `pExecute = 1`. The plan ID is at `/body/ID`.
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants
cThisProcName = GetProcessName();
cUserName     = TM1User();
sMessages     = '{"Process": "'|cThisProcName|'", "User": "'|cUserName|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUserName|'''."], "Error": []}';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );

pDefaultParameters = '{
  "pConnectionName":        "",
  "pMessage":             "",
  "pAuthor":              "",
  "pEmail":               "",
  "pBranch":              "",
  "pNewBranch":           "",
  "pForce":               0,
  "pUsername":            "",
  "pPassword":            "",
  "pPublicKey":           "",
  "pPrivateKey":          "",
  "pPassphrase":          "",
  "pExecute":             0,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0
}';

pPassedParameters = '{
  "pConnectionName":        '|StringToJson( pConnectionName          )|',
  "pMessage":             '|StringToJson( pMessage               )|',
  "pAuthor":              '|StringToJson( pAuthor                )|',
  "pEmail":               '|StringToJson( pEmail                 )|',
  "pBranch":              '|StringToJson( pBranch                )|',
  "pNewBranch":           '|StringToJson( pNewBranch             )|',
  "pForce":               '|NumberToString( pForce               )|',
  "pUsername":            '|StringToJson( pUsername              )|',
  "pPassword":            '|StringToJson( pPassword              )|',
  "pPublicKey":           '|StringToJson( pPublicKey             )|',
  "pPrivateKey":          '|StringToJson( pPrivateKey            )|',
  "pPassphrase":          '|StringToJson( pPassphrase            )|',
  "pExecute":             '|NumberToString( pExecute             )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );

IF( JsonType( JsonGet( pJson, '/pConnectionName' ) ) @= 'string' );
  pConnectionName = JsonToString( pJson, '/pConnectionName' );
ELSE;
  pConnectionName = JsonGet( pJson, '/pConnectionName' );
ENDIF;
pMessage             =                 JsonToString( pJson, '/pMessage'             );
pAuthor              =                 JsonToString( pJson, '/pAuthor'              );
pEmail               =                 JsonToString( pJson, '/pEmail'               );
pBranch              =                 JsonToString( pJson, '/pBranch'              );
pNewBranch           =                 JsonToString( pJson, '/pNewBranch'           );
pForce               = StringToNumber( JsonToString( pJson, '/pForce'               ) );
pUsername            =                 JsonToString( pJson, '/pUsername'            );
pPassword            =                 JsonToString( pJson, '/pPassword'            );
pPublicKey           =                 JsonToString( pJson, '/pPublicKey'           );
pPrivateKey          =                 JsonToString( pJson, '/pPrivateKey'          );
pPassphrase          =                 JsonToString( pJson, '/pPassphrase'          );
pExecute             = StringToNumber( JsonToString( pJson, '/pExecute'             ) );
pLogOutput           = StringToNumber( JsonToString( pJson, '/pLogOutput'           ) );
pStrictErrorHandling = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling' ) );

IF( pLogOutput = 1 );
  LogOutput( 'INFO', 'Process: ' | cThisProcName | ' | Author: ' | pAuthor | ' | Branch: ' | pBranch );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

#################################################################################################
#Region - Validate Parameters

IF( pAuthor @= '' );
  pAuthor = cThisProcName | ' called by user ' | cUserName;
ENDIF;
IF( pMessage @= '' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"pMessage is required."' );
ENDIF;
IF( pEmail @= '' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"pEmail is required."' );
ENDIF;

IF( JsonSize( sMessages, '/Error' ) <> 0 );
  IF( pLogOutput = 1 );
    LogOutput( 'ERROR', 'Validation failed: ' | JsonToString( sMessages, '/Error' ) );
  ENDIF;
  IF( pStrictErrorHandling = 1 );
    ProcessQuit;
  ELSE;
    ProcessBreak;
  ENDIF;
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

#################################################################################################
#Region - Get Connection Details

# Get Database Connection Details
sDatabaseParameterType = JsonType( pConnectionName );
IF( sDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pConnectionName, 'pJson', pJson ); sConnectionDetails = sBedrockReturnValue;
ELSE;
  sConnectionDetails = pConnectionName;
ENDIF;
pJson = JsonAdd( pJson, 'pConnectionName', sConnectionDetails );

sURL        = JsonToString( sConnectionDetails, '/sURL' );
sAuthHeader = JsonToString( sConnectionDetails, '/sAuthHeader' );

### Authentication headers for requests to this connection
sAuthHeaders = '[]';
IF( JsonToString( sConnectionDetails, '/sAuthHeader' ) @<> '' );
  sAuthHeaders = JsonAdd( sAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sConnectionDetails, '/sSID' ) @<> '' );
  sAuthHeaders = JsonAdd( sAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sConnectionDetails, '/sSID' ) ) );
ENDIF;

#EndRegion - Get Connection Details
#################################################################################################

#################################################################################################
#Region - Build Request Body

sBody = '{"Message": ' | StringToJson( pMessage ) |
        ', "Author": ' | StringToJson( pAuthor  ) |
        ', "Email": '  | StringToJson( pEmail   ) ;

IF( pBranch @<> '' );
  sBody = sBody | ', "Branch": ' | StringToJson( pBranch );
ENDIF;
IF( pNewBranch @<> '' );
  sBody = sBody | ', "NewBranch": ' | StringToJson( pNewBranch );
ENDIF;
IF( pForce = 1 );
  sBody = sBody | ', "Force": true';
ENDIF;
IF( pUsername @<> '' );
  sBody = sBody | ', "Username": ' | StringToJson( pUsername );
ENDIF;
IF( pPassword @<> '' );
  sBody = sBody | ', "Password": ' | StringToJson( pPassword );
ENDIF;
IF( pPublicKey @<> '' );
  sBody = sBody | ', "PublicKey": ' | StringToJson( pPublicKey );
ENDIF;
IF( pPrivateKey @<> '' );
  sBody = sBody | ', "PrivateKey": ' | StringToJson( pPrivateKey );
ENDIF;
IF( pPassphrase @<> '' );
  sBody = sBody | ', "Passphrase": ' | StringToJson( pPassphrase );
ENDIF;

sBody = sBody | '}';

#EndRegion - Build Request Body
#################################################################################################

#################################################################################################
#Region - Create Push Plan

ExecuteProcess( '}bedrock.process.execute_http_request',
  'pMethod',  'POST',
  'pURL',     sURL | '/GitPush',
  'pHeaders', sAuthHeaders,
  'pBody',    sBody,
  'pJson',    pJson
);

sPlanResponse = sBedrockReturnValue;
sPlanId       = JsonToString( sPlanResponse, '/body/ID' );

IF( pLogOutput = 1 );
  LogOutput( 'INFO', 'GitPush plan created. PlanId: ' | sPlanId );
ENDIF;

#EndRegion - Create Push Plan
#################################################################################################

#################################################################################################
#Region - Execute Plan (if requested)

IF( pExecute = 1 );

  IF( sPlanId @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"GitPush plan was created but the plan ID could not be extracted from the response. Cannot execute."' );
    IF( pLogOutput = 1 );
      LogOutput( 'ERROR', 'Plan response: ' | sPlanResponse );
    ENDIF;
    IF( pStrictErrorHandling = 1 );
      ProcessQuit;
    ELSE;
      ProcessBreak;
    ENDIF;
  ENDIF;

  ExecuteProcess( '}bedrock.git.plan.execute',
    'pPlanId', sPlanId,
    'pJson',   pJson
  );

  IF( pLogOutput = 1 );
    LogOutput( 'INFO', 'GitPush plan executed. PlanId: ' | sPlanId );
  ENDIF;

ENDIF;

### Restore the plan response as the return value regardless of execute path
sBedrockReturnValue = sPlanResponse;

#EndRegion - Execute Plan (if requested)
#################################################################################################

EpilogProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

##################################################################################################
#Region - Cleanup

IF( sDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.process.execute_http_request', 'pMethod', 'POST', 'pURL', sURL | '/ActiveSession/tm1.Close', 'pHeaders', sAuthHeaders );
ENDIF;

#EndRegion - Cleanup
#################################################################################################
